#include <stdio.h>
#include <string.h>

static const char map_table[26] = {
    '2', '2', '2',      /* a, b, c */
    '3', '3', '3',      /* d, e, f */
    '4', '4', '4',      /* g, h, i */
    '5', '5', '5',      /* j, k, l */
    '6', '6', '6',      /* m, n, o */
    '7', '7', '7', '7', /* p, q, r, s */
    '8', '8', '8',      /* t, u, v */
    '9', '9', '9', '9'  /* w, x, y, z */
};

int main(void) {
    char n_str[1005];
    if (scanf("%1004s", n_str) != 1) return 0;

    int m;
    if (scanf("%d", &m) != 1) return 0;

    int n_len = (int)strlen(n_str);
    int count = 0;
    char c_str[1005];

    for (int i = 0; i < m; i++) {
        if (scanf("%1004s", c_str) != 1) break;

        int c_len = (int)strlen(c_str);
        if (c_len != n_len) {
            continue;
        }

        int match = 1;
        for (int j = 0; j < n_len; j++) {
            if (map_table[c_str[j] - 'a'] != n_str[j]) {
                match = 0;
                break;
            }
        }

        if (match) {
            count++;
        }
    }

    printf("%d\n", count);
    return 0;
}
